previewCss:
.darma-loader-darma-b11-campfire { --accent: var(--loader-color, #f97316); --accent-2: var(--loader-secondary-color, #fde047); width: var(--loader-size, 84px); height: var(--loader-size, 84px); position: relative; }
.darma-loader-darma-b11-campfire span { position: absolute; bottom: 24%; left: 50%; width: 32%; height: 46%; margin-left: -16%; background: radial-gradient(ellipse at 50% 82%, #fff, var(--accent-2) 34%, var(--accent) 76%); border-radius: 0 50% 50% 50%; transform: rotate(45deg); transform-origin: 50% 82%; box-shadow: 0 0 calc(var(--loader-size, 84px) * .2) color-mix(in srgb, var(--accent) 55%, transparent); animation: darma-loader-darma-b11-campfire-fire-a calc(var(--loader-speed, 1s) * .5) ease-in-out infinite alternate; }
.darma-loader-darma-b11-campfire span:nth-child(2) { width: 20%; height: 30%; margin-left: -10%; bottom: 30%; background: radial-gradient(ellipse at 50% 82%, #fff, var(--accent-2) 45%, var(--accent) 85%); animation: darma-loader-darma-b11-campfire-fire-b calc(var(--loader-speed, 1s) * .38) ease-in-out infinite alternate; box-shadow: none; }
.darma-loader-darma-b11-campfire::before, .darma-loader-darma-b11-campfire::after { content: ''; position: absolute; bottom: 14%; left: 50%; width: 46%; height: calc(var(--loader-size, 84px) * .06); margin-left: -23%; background: linear-gradient(#92400e, #78350f); border-radius: 4px; }
.darma-loader-darma-b11-campfire::before { transform: rotate(16deg); }
.darma-loader-darma-b11-campfire::after { transform: rotate(-16deg); }
@keyframes darma-loader-darma-b11-campfire-fire-a { 0% { transform: rotate(45deg) scale(1, 1); } 100% { transform: rotate(45deg) scale(.88, 1.16); } }
@keyframes darma-loader-darma-b11-campfire-fire-b { 0% { transform: rotate(45deg) scale(1.1, .9); } 100% { transform: rotate(45deg) scale(.9, 1.1); } }

